ST.xhtml:p:
pv := level;
sp := Setpoint;
tankstatus := statustank; (* 1=OK, 2=WARNING, 3=BROKEN *)

if ValveButtonBoth then 
state := 4;
else
if pv >= 90 then
state := 1; (* 0= HOLD,  1= DUMP (to not anger management), 2= DRAIN, 3:= FILL *) 
elsif pv > sp + 3 then
state := 2;
elsif pv < sp - 3 then
state :=3;
else
state :=0;
end_if;
end_if;

CASE state OF 
1: inlet := 0;
   outlet := 99;
2: inlet :=0;
   outlet := 70;
3: inlet :=50;
   outlet:=0;
4: inlet :=100;
   outlet :=100; (* expect for the increase due to the tank behaviour *)
0: inlet :=0;
   outlet :=10; (* minimum amount of flow at all times*)
end_case;
